package com.fasttravel.dao.impl;import com.fasttravel.dao.BookingDAO;import com.fasttravel.entity.Booking;import com.fasttravel.repository.BookingRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Repository;import java.time.LocalDateTime;import java.util.*;
@Repository @RequiredArgsConstructor public class BookingDAOImpl implements BookingDAO{private final BookingRepository repo;public Booking save(Booking e){return repo.save(e);}public Optional<Booking> findById(Long id){return repo.findById(id);}public List<Booking> findAll(){return repo.findAll();}public void deleteById(Long id){repo.deleteById(id);}public Optional<Booking> findByCode(String c){return repo.findByCode(c);}public List<Booking> findByUser(Long id){return repo.findByUserIdOrderByCreatedAtDesc(id);}public List<Booking> findExpiredPending(LocalDateTime now){return repo.findByStatusAndExpiresAtBefore(Booking.Status.PENDING_PAYMENT,now);}}
